public class sort {

    public static void sort (Comparable[] v) {

        for (int i = 0; i < v.length; i += 1) {

            for (int j = i - 1; j >= 0 && v[j].compareTo(v[j + 1]); j -= 1) {

                swap(v, j);

            }

        }

    protected static void swap(Comparable[] v, int k) {

        Comparable temp = v[k];

        v[k] = v[k+1];

        v[k+1] = temp;

    }}

